INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (1, '400', '400', NULL, NULL, '/lore/400/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (2, 'Académie de l’arcane', 'academie-de-larcane', NULL, NULL, '/lore/academie-de-larcane/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (3, 'Accessoires', 'accessoires', NULL, NULL, '/ressources/accessoires/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (4, 'Acquis', 'acquis', 'Les points d’une compétence qui ne se répartissent pas, mais se gagnent : par l’entraînement, les dons de la race, de l’ethnie et de la classe, l’armure portée, le métier et les accessoires, et la fiche de personnage du site les additionne. En règle générale, ils ne dépassent pas 5 par point de la caractéristique, le +1 de la magie innée compris.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (5, 'Action', 'action', 'L’action principale du tour, qui sert à attaquer, à lancer un sort, à utiliser un objet, à sprinter, à utiliser un don de type Action ou à faire une quatrième action rapide.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (8, 'Alchimie', 'alchimie', NULL, NULL, '/ressources/alchimie/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (9, 'Alchimie primitive', 'alchimie-primitive', NULL, NULL, '/ressources/alchimie-primitive/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (10, 'Alignement', 'alignement', 'Moralité et Éthique du personnage. Évolue en fonction des actes accomplis selon les deux axes Bon/Mauvais et Loyal/Chaotique', NULL, '/regles/alignement/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (11, 'Altération d’état', 'alteration-detat', 'Un changement de la condition d’un personnage (poison, brûlure, peur, paralysie…) qui lui inflige des malus, souvent pendant plusieurs tours. Il en existe vingt, physiques ou mentales, et la plupart ont trois stades, de plus en plus forts.', NULL, '/regles/alterations-d-etats/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (12, 'Âme', 'ame', '{{cout-secondaire|Ressource secondaire}} de la {{magie-de-la-necromancie|nécromancie}}. C’est une réserve de 10 unités par défaut. Elle est utilisé pour la plupart des sorts en plus du {{chakra|chakra}}. La réserve d''âmes se recharge de 1 par tour en combat.', 'magie:necromancie', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (13, 'Amélioration', 'amelioration', 'Le niveau d’une arme (de +1 à +10), d’une armure ou d’un bouclier (de +1 à +5). Le niveau choisi donne le bonus qu’il écrit, qui est déjà le total : +10 aux dégâts pour une arme +5, +10 AP et +10 AM pour une armure +5, +10 AP pour un bouclier +5. On paie toutes les étapes, une à une, sans en sauter aucune. Les crans de {{solidite|solidité}} : pour une arme, +1 du +5 au +9 et +2 au +10 ; pour une armure, +1 au +4 comme au +5 ; pour un bouclier, les crans s’additionnent, +1 du +1 au +4 et +2 au +5.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (14, 'Anansi', 'anansi-race', NULL, 'race:hybride', '/races/anansi/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (15, 'Anansi', 'anansi-classe', NULL, 'classe:raciales', '/classes/anansi/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (16, 'Anna', 'anna', NULL, NULL, '/lore/anna/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (17, 'Arbalétrier', 'arbaletrier', NULL, 'classe:distance', '/classes/arbaletrier/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (18, 'Archer', 'archer', NULL, 'classe:distance', '/classes/archer/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (19, 'Archimage', 'archimage', NULL, 'classe:speciales', '/classes/archimage/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (20, 'Armes', 'armes', NULL, NULL, '/ressources/armes/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (21, 'Armure magique', 'armure-magique', 'Les points que l’armure retire aux dégâts des sorts. L’AM vient de la race, de l’ethnie, des classes magiques (4 chacune : voir {{classe-magique|Classe magique}}), des accessoires et de l’armure portée.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (22, 'Armure physique', 'armure-physique', 'Les points que l’armure retire aux dégâts des armes. Contre un coup d’estoc, de taille ou de frappe, l’armure portée les compte double ou moitié, selon qu’elle y résiste ou y est faible.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (23, 'Armures', 'armures', NULL, NULL, '/ressources/armures/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (24, 'Armurier', 'armurier', NULL, NULL, '/metiers/#metier-armurier', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (25, 'Artisanat', 'artisanat', 'Fabriquer des objets, ce que seuls certains métiers permettent : il faut le bon métier. La compétence d’artisanat vaut 10 × la première caractéristique du métier + 10 × la seconde.', NULL, '/regles/artisanat/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (26, 'Attaque discrète', 'attaque-discrete', 'Frapper une cible qui ne vous voit pas venir, pour un dé de dégâts en plus. À ne pas confondre avec l’attaque sournoise, qui vient d’une classe.', NULL, '/regles/les-attaques-discretes/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (27, 'Attaque d’opportunité', 'attaque-dopportunite', 'Une attaque offerte hors de son tour, quand un adversaire rate son attaque contre vous sur un échec critique, quand il sort de votre zone d’influence (sauf si c’est vous qui l’en faites sortir), ou quand un don le permet. Une seule par tour et par joueur, sauf don qui en permet plus, et seulement une action simple.', NULL, '/regles/les-attaques-d-opportunite/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (28, 'Se défendre', 'se-defendre', NULL, NULL, '/regles/attaque-et-defense/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (29, 'Attaque gratuite', 'attaque-gratuite', 'L’attaque que permet un adversaire qui quitte votre {{zone-dinfluence|zone d’influence}} : c’est une {{attaque-dopportunite|attaque d’opportunité}}, avec ses limites.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (30, 'Attaquer', 'attaquer', NULL, NULL, '/regles/attaquer-et-se-defendre/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (31, 'Attributs', 'attributs', 'Les valeurs de base du personnage (santé, {{chakra|chakra}}, {{barriere|barrière}}, {{corruption|corruption}}, vitesse, initiative, armure de base), et la quatrième barre pour la Nécromancie et la magie du Sang.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (32, 'Aurora', 'aurora', NULL, 'magie:lumiere', '/lore/aurora/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (33, 'Balogne', 'balogne', NULL, NULL, '/lore/balogne/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (34, 'Barde', 'barde', NULL, 'classe:magiques', '/classes/barde/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (35, 'Bardiche du Bourreau déchiré', 'bardiche-du-bourreau-dechire', NULL, NULL, '/lore/bardiche-du-bourreau-dechire/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (36, 'Barrage Argenté', 'barrage-argente', NULL, NULL, '/lore/barrage-argente/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (37, 'Barrière', 'barriere', 'Manifestation physique dérivée du {{chakra|Chakra}} d''un individu. Elle agit comme une seconde peau invisible protégeant le corps de blessures. Abrégée BA, elle vaut la moitié du {{chakra|chakra}} total, arrondie à l’inférieur, plus les bonus de la race et de la classe. Sauf indication contraire, elle prend les coups avant la santé.', 'attribut:barriere', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (38, 'Bâton de la destruction', 'baton-de-la-destruction', NULL, NULL, '/lore/baton-de-la-destruction/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (39, 'Bâton magique', 'baton-magique', 'Catalyseur à conserver à la ceinture pour améliorer l''usage de la magie.', NULL, '/ressources/objets-a-la-ceinture/#batons-magiques', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (40, 'Battlemap', 'battlemap', 'Voir {{carte-de-combat|Carte de combat}}.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (41, 'Bauc', 'bauc', NULL, NULL, '/lore/bauc/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (42, 'Bestiaire', 'bestiaire', NULL, NULL, '/bestiaire/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (43, 'Biclassage', 'biclassage', 'Personnage ayant de choisir de suivre la voie de deux classes en simultanée.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (44, 'Bienvenue dans Maverick', 'bienvenue-dans-maverick', NULL, 'partie:decouvrir', '/decouvrir/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (45, 'Bimane', 'bimane', NULL, 'classe:melee', '/classes/bimane/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (46, 'Blessure et mort', 'blessure-et-mort', NULL, NULL, '/regles/blessures-et-etats/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (47, 'Bois du printemps', 'bois-du-printemps', NULL, NULL, '/lore/bois-du-printemps/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (48, 'Boss', 'boss', 'Un ennemi pensé pour affronter une équipe de quatre joueurs. Il a deux initiatives par tour, et plus de parades et d’esquives que les autres dans certaines postures.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (49, 'Bouclier', 'bouclier', 'Une forme, sa classe de 1 à 5 (Bocle, Targe, Bouclier Rond, Écu, Pavois), et une matière, qui donne sa solidité. Ses AP et son AM ne comptent que sur une parade partielle faite avec lui, et son poids demande une Force minimum.', NULL, '/ressources/bouclier/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (50, 'Brock', 'brock', NULL, 'magie:sang', '/lore/brock/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (51, 'càc', 'cac', NULL, NULL, NULL, 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (52, 'Camnau', 'camnau', NULL, NULL, '/lore/camnau/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (53, 'Campagne', 'campagne', 'Une aventure en plusieurs séances, qui part d’un point A pour arriver à un point B ; les joueurs y font partie de l’écriture de l’histoire. Voir aussi {{one-shot|One shot}}.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (54, 'capacité de classe', 'capacite-de-classe', NULL, NULL, NULL, 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (55, 'Capse', 'capse', NULL, 'magie:espace-temps', '/lore/capse/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (56, 'Caractéristique', 'caracteristique', '{{force|Force}}, {{volonte|Volonté}}, {{intelligence|Intelligence}}, {{perception|Perception}}, {{social|Social}} et / ou {{agilite|Agilité}}, pouvant aller de 1 à 4 hors magie innée. Certaines {{race|races}} limites d''avantage ces valeurs.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (57, 'Carte de combat', 'carte-de-combat', 'Une carte quadrillée vue de haut, où le MJ dessine les obstacles d’un combat et où l’on compte les distances en cases. Il peut s’en passer pour un combat rapide.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (58, 'Ceinture', 'ceinture', 'Trois emplacements pour des objets à portée de main (fioles, carquois, bâtons magiques…), qui s’utilisent en une action rapide au lieu d’une action entière ; au plus 3 exemplaires du même objet dans chacun.', NULL, '/ressources/objets-a-la-ceinture/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (59, 'Celsius', 'celsius', NULL, 'magie:glace', '/lore/celsius/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (60, 'Chakra', 'chakra', 'Énergie consommée lors de l''utilisation de magie. Quand le chakra est épuisé, la santé est consommée à la hauteur de 3 points pour un de Chakra. Abrégé CK, il compte les points de magie du personnage, que dépensent ses sorts, et vient de la race, de la ou des classes et des magies.', 'attribut:chakra', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (61, 'Champicer', 'champicer', NULL, NULL, '/lore/champicer/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (62, 'Champieu', 'champieu', NULL, NULL, '/lore/champieu/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (63, 'Chapelle des Os', 'chapelle-des-os', NULL, 'magie:necromancie', '/lore/chapelle-des-os/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (64, 'Chargement (Mage Vert)', 'chargement-mage-vert', NULL, NULL, '/capacites/mage-vert-chargement/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (65, 'Chronologie', 'chronologie', NULL, NULL, '/chronologie/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (66, 'Classe', 'classe', 'La façon de se battre du personnage. Elle a son propre niveau, et lui donne de la santé, du {{chakra|chakra}} et de la {{barriere|barrière}}, des maîtrises d’armes et d’armures, un équipement de départ et des dons. Les classes se rangent en cinq catégories : physiques au corps à corps, physiques à distance, magiques, raciales et spéciales.', NULL, '/classes/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (67, 'Classe magique', 'classe-magique', 'Une classe de la catégorie des classes magiques ; l’Archimage, rangée dans les classes spéciales, en est une aussi. Elle donne 4 AM et compte comme une condition pour les emplacements de sorts. La seconde spécialité de chaque classe raciale, et celle du Flagelleur, compte elle aussi comme classe magique : elle donne 4 AM et compte comme une condition pour les emplacements de sorts.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (68, 'Classe raciale', 'classe-raciale', 'La classe propre à une race hybride, qui porte son nom. Le Drassah’thac, hybride, n’en a pas.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (69, 'Clerc', 'clerc', NULL, 'classe:magiques', '/classes/clerc/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (70, 'Cloche d’or', 'cloche-dor', NULL, NULL, '/lore/cloche-dor/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (71, 'codex', 'codex', NULL, NULL, '/lore/codex/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (72, 'Collines humides', 'collines-humides', NULL, NULL, '/lore/collines-humides/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (73, 'Coma', 'coma', 'L’état d’un personnage dont la santé tombe à 0 ou moins. Inconscient, il fait des jets de Survie : un seul réussi le stabilise, trois ratés et il meurt.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (74, 'Compagnie du Fer Noir', 'compagnie-du-fer-noir', NULL, NULL, '/lore/compagnie-du-fer-noir/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (75, 'Compétence', 'competence', 'Un savoir-faire lié à une {{caracteristique|Caractéristique}}, dont le score est déterminé par un score {{naturel|Naturel}} et un score {{acquis|Acquis}}, ainsi qu''un bonus variable en fonction de la situation. Détermine un pourcentage de réussite.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (76, 'Composants', 'composants', NULL, NULL, '/ressources/composants/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (77, 'Confrérie du Sang', 'confrerie-du-sang', NULL, NULL, '/lore/confrerie-du-sang/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (78, 'Corruption', 'corruption', 'Poison du {{chakra|chakra}} : chaque point de corruption prend la place d''un point de chakra, jusqu''au maximum du chakra ; le repos et la méditation ne la font pas baisser. Au maximum, le personnage a deux semaines pour en retirer un point, sinon il meurt et devient une abomination à moins d''en maîtriser la {{magie-de-la-corruption|magie}}', 'magie:corruption', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (79, 'Coût secondaire', 'cout-secondaire', 'Ce qu’un sort coûte en plus de son {{chakra|chakra}}.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (80, 'Couturier', 'couturier', NULL, NULL, '/metiers/#metier-couturier', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (81, 'Créature invoquée', 'creature-invoquee', 'Une créature appelée par un sort. Elle n’a pas d’échelle de puissance. Sa puissance est indexée sur le {{niveau-de-puissance-magique|NPM}}.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (82, 'Créer son personnage', 'creer-son-personnage', NULL, 'partie:creer', '/regles/creer-son-personnage/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (83, 'Croc du Volcan', 'croc-du-volcan', NULL, NULL, '/lore/croc-du-volcan/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (84, 'Croix', 'croix', 'Une marque sous une caractéristique, laissée par une blessure grave, un traumatisme, une maladie, une mauvaise nuit ou certaines altérations d’état. Une croix retire 20 % à tous les jets de la caractéristique ; deux la rendent inutilisable, elle et ses compétences.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (85, 'Cuirassé', 'cuirasse', NULL, 'classe:melee', '/classes/cuirasse/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (86, 'Défense partielle', 'defense-partielle', 'Une parade ou une esquive réussie, mais moins bonne que l’attaque. Les dégâts sont divisés par 2. Si c’est une parade partielle faite au bouclier, ses AP et son AM comptent : c’est le seul cas où ils comptent. Contre une réussite critique, seule une défense critique peut être partielle.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (87, 'Dégâts', 'degats', 'Ce que perd la cible d’un coup réussi, en santé ou en {{barriere|barrière}}, une fois retirée son armure.', NULL, '/regles/les-degats/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (88, 'Dés', 'des', 'Un jet de dés détermine l''issue d''une action aux conséquences incertaines.', NULL, '/regles/jet-de-des/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (89, 'Dieu choisi', 'dieu-choisi', 'Dieu ou déesse que le personnage a choisi de prier en plus de son dieu ou sa déesse {{dieu-inne|inné(e)}}', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (90, 'Dieu inné', 'dieu-inne', 'Affinité particulière avec la divinité lié à la {{magie-innee|Magie innée}} du personnage.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (91, 'Dimitri', 'dimitri', NULL, 'magie:terre', '/lore/dimitri/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (92, 'distance', 'distance', NULL, NULL, NULL, 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (93, 'Dombourg', 'dombourg', NULL, NULL, '/lore/dombourg/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (94, 'Don', 'don', 'Une capacité particulière, donnée par la race, par la classe ou par les événements de l’aventure. Un don est passif (toujours effectif), actif (à déclarer pour que son effet fonctionne), d’action (il prend l’action du tour) ou de réaction (il se joue en dehors de son tour).', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (95, 'Don de base', 'don-de-base', 'Le don que donne la race, Méditation (pour récupérer du {{chakra|chakra}}) ou Repos (pour récupérer de la santé et du {{chakra|chakra}}) ; une action, trois fois par jour.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (96, 'Donjon Pas bon', 'donjon-pas-bon', NULL, NULL, '/regles/donjon-pas-bon/', 1, NULL, NULL);
