INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (104, 'Échec critique', 'echec-critique', 'Un résultat de 96 à 100 au D100. L’action rate complètement, et cela coûte quelque chose : un sort au double de son coût, une défense où l’armure ne compte plus…', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (105, 'Échelle de puissance', 'echelle-de-puissance', 'Puissance approximative d''un monstre, de 1 à 10. 
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (106, 'Église du Sel', 'eglise-du-sel', NULL, NULL, '/lore/eglise-du-sel/', 1, NULL, NULL);
