INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (111, 'Elfe noir', 'elfe-noir', NULL, 'race:pure', '/races/elfe-noir/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (112, 'Embuscade', 'embuscade', 'Consommer l’action de son tour pour attendre un ennemi, et lui porter une attaque d’opportunité dès qu’il entre dans la zone voulue. La posture de vigilance la déjoue.', NULL, '/regles/l-embuscade/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (113, 'Empire Argenté', 'empire-argente', NULL, NULL, '/lore/empire-argente/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (114, 'Empire Humain', 'empire-humain', NULL, NULL, '/lore/empire-humain/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (115, 'Emplacement de sort', 'emplacement-de-sort', 'Leur nombre déterminer combien de sorts différents un personnage peut utiliser parmi la listes des sorts connus. Augmenté par le {{niveau-de-puissance-magique|NPM}} du personnage et par le fait d''avoir accès à une {{magie-acquise|Magie acquise}} ou à la {{super-magie|Super Magie}}', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (116, 'Entraînement', 'entrainement', 'Un jet de D100 qui fait gagner des points d’acquis dans une compétence, auprès d’un entraîneur ou d’un PNJ important. Il ne fait progresser que 15 compétences au plus, et chacune de 10 % au plus.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (117, 'Éoline', 'eoline', NULL, 'magie:vent', '/lore/eoline/', 1, NULL, NULL);
