INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (119, 'Erisia', 'erisia', NULL, NULL, '/lore/erisia/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (120, 'Esquive', 'esquive', 'Éviter un coup, avec la compétence Esquive (Agilité). Voir aussi {{parade|Parade}} et {{defense-partielle|Défense partielle}}.', 'caracteristique:agilite', NULL, 0, NULL, NULL);
