INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (160, 'Classe hybride', 'classe-hybride', 'Classe dont la spécialité détermine si la class deviens une classe magique ou non.', NULL, NULL, 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (161, 'Hybride animal', 'hybride-animal', 'En opposition aux races dites {{race-pure|pures}}', NULL, NULL, 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (162, 'Initiative', 'initiative', 'Ce qui fixe l’ordre de jeu en combat. À chaque tour, chacun lance 1D20 et ajoute un bonus qui dépend de son Agilité ; on joue du plus haut résultat au plus bas.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (163, 'Instant Cast', 'instant-cast', 'Une action qui ne prend pas l’action du tour. Trois au plus par tour, jamais deux fois la même, toujours avant l’action ; un sort IC ne consomme pas le tour, sauf sur un échec critique.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (164, 'Intervention', 'intervention', 'En posture défensive, parer ou esquiver un coup à la place d’un allié adjacent.', NULL, NULL, 0, NULL, NULL);
