INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (204, 'Mage Bleu', 'mage-bleu', NULL, 'classe:magiques', '/classes/mage-bleu/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (205, 'Mage Rouge', 'mage-rouge', NULL, 'classe:magiques', '/classes/mage-rouge/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (206, 'Mage Vert', 'mage-vert', NULL, 'classe:magiques', '/classes/mage-vert/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (207, 'Magie acquise', 'magie-acquise', 'Magie secondaire apprise par l''expérience. Donne accès à plus de sort, mais ferme la voie à la {{super-magie|Super Magie}}', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (208, 'Magie de la Corruption', 'magie-de-la-corruption', 'Magie primordiale, elle manipule la {{corruption|Corruption}} dans sa forme pure et brute. Elle consume et empoisonne.  Augmente l''{{intelligence|Intelligence}}.', 'magie:corruption', '/magies/magie-de-la-corruption/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (209, 'Magie de la Foudre', 'magie-de-la-foudre', 'Magie élémentaire, vive et impulsive pour des esprits prompts à l''action. Augmente l''{{agilite|Agilité}}.', 'magie:foudre', '/magies/magie-de-la-foudre/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (210, 'Magie de la Glace', 'magie-de-la-glace', 'Magie élémentaire, imperturbable. Un rempart rigide pour refroidir les ardeurs d''un assaillant. Augmente l''{{intelligence|Intelligence}}.', 'magie:glace', '/magies/magie-de-la-glace/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (211, 'Magie de la Lumière', 'magie-de-la-lumiere', 'Magie élémentaire, aussi appelée magie sacrée, capable de protection, guérison, sacrifice de soit et fanatisme aveugle.  Augmente la {{perception|Perception}}.', 'magie:lumiere', '/magies/magie-de-la-lumiere/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (212, 'Magie de la Nécromancie', 'magie-de-la-necromancie', 'Magie primordiale de la Mort, tout aussi employer pour asservir les non-morts que pour guider les âmes vers l''au-delà. Augmente la {{volonte|volonté}}.', 'magie:necromancie', '/magies/magie-de-la-necromancie/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (213, 'Magie de la Terre', 'magie-de-la-terre', 'Magie élémentaire, liée à la nature et la roche, s''érigeant en protecteur inflexible. Augmente la {{force|Force}}.', 'magie:terre', '/magies/magie-de-la-terre/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (214, 'Magie de l''Arcane', 'magie-de-larcane', 'Magie primordiale, elle manipule le {{chakra|Chakra}} dans sa forme pure et brute. Malléable et polyvalente.  Augmente l''{{intelligence|Intelligence}}.', 'magie:arcane', '/magies/magie-de-larcane/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (215, 'Magie de l''Eau', 'magie-de-leau', 'Magie élémentaire, stable et impassible, peut tout aussi bien soigner que déchaîner la fureur des océans.  Augmente le {{social|Social}}.', 'magie:eau', '/magies/magie-de-leau/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (216, 'Magie de l''Espace/Temps', 'magie-de-lespace-temps', 'Magie primordiale complexe et rigide, remaniant les loi de la physique. Faible en apparence, elle est l''outils parfait des stratèges.  Augmente l''{{intelligence|Intelligence}}.', 'magie:espace-temps', '/magies/magie-de-lespace-temps/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (217, 'Magie de l''Ombre', 'magie-de-lombre', 'Magie élémentaire sournoise orientée vers les entraves, la ruse et des secrets. Augmente la {{perception|Perception}}.', 'magie:ombre', '/magies/magie-de-lombre/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (218, 'Magie du Feu', 'magie-du-feu', 'Magie élémentaire, destructrice et impulsive, faite pour réagir à l''instinct. Augmente le {{social|Social}}.', 'magie:feu', '/magies/magie-du-feu/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (219, 'Magie du Sang', 'magie-du-sang', 'Magie primordiale, sauvage et combative. Renforce directement le physique.  Augmente la {{force|Force}}.', 'magie:sang', '/magies/magie-du-sang/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (220, 'Magie du Vent', 'magie-du-vent', 'Magie élémentaire liée au cieux, aux grands espaces et à la vitesse. Augmente l''{{agilite|Agilité}}.', 'magie:vent', '/magies/magie-du-vent/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (221, 'Magie du Vide', 'magie-du-vide', 'Magie primordiale, tordant l''esprit et la réalité, neutralisant les autres magies. Augmente la {{volonte|volonté}}.', 'magie:vide', '/magies/magie-du-vide/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (222, 'Magie innée', 'magie-innee', 'Magie héritée à la naissance depuis l''un des deux parents. Influence fortement l''apparence du personnage et lui donne une caractéristique spécifique.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (223, 'Magies', 'magies', NULL, NULL, '/magies/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (224, 'magique', 'magique', NULL, NULL, NULL, 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (225, 'Maître du jeu', 'maitre-du-jeu', 'Celui qui raconte l’histoire, joue les PNJ et les monstres, et juge de ce qui est possible, improbable ou impossible.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (226, 'Maîtrise d’arme', 'maitrise-darme', 'Le savoir-faire avec une catégorie d’arme. Sans maîtrise, l’arme lance 1 dé de dégâts ; chaque point de maîtrise en ajoute un, jusqu’à 4 points au plus par catégorie, donc 5 dés. Les points de toutes les sources s’additionnent, jusqu’à ce plafond ; au-delà, la fiche le signale, et les points en trop ne donnent pas de dé.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (227, 'Majin', 'majin', NULL, 'race:pure', '/races/majin/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (228, 'Maladie', 'maladie', NULL, NULL, '/ressources/maladie/', 1, NULL, NULL);
