INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (235, 'Médecin sans frontière', 'medecin-sans-frontiere', NULL, NULL, '/lore/medecin-sans-frontiere/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (236, 'Médusain', 'medusain-race', NULL, 'race:hybride', '/races/medusain/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (237, 'Médusain', 'medusain-classe', NULL, 'classe:raciales', '/classes/medusain/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (238, 'Mercenaire', 'mercenaire', NULL, 'classe:melee', '/classes/mercenaire/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (239, 'Météo', 'meteo', NULL, NULL, '/regles/meteo/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (240, 'Métier', 'metier', 'Un savoir-faire choisi à la création ou plus tard dans l’aventure. Il donne des bonus d’acquis ou d’attribut, des objets de départ et, pour certains, l’artisanat.', NULL, '/metiers/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (241, 'Mineur', 'mineur', NULL, NULL, '/metiers/#metier-mineur', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (242, 'Minotaure', 'minotaure-race', NULL, 'race:hybride', '/races/minotaure/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (243, 'Minotaure', 'minotaure-classe', NULL, 'classe:raciales', '/classes/minotaure/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (244, 'Mirada', 'mirada', NULL, 'magie:arcane', '/lore/mirada/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (245, 'Mode Hyper', 'mode-hyper', 'État de surpuissance. Pour quelques tours, une fois par semaine, la magie du personnage ne fait plus qu’un avec lui.', NULL, '/regles/le-mode-hyper/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (246, 'Mode Super', 'mode-super', 'Un équivalent moins puissant du Mode Hyper : une symbiose avec un objet légendaire ou enchanté.', NULL, '/regles/mode-super/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (247, 'Moine', 'moine', NULL, 'classe:melee', '/classes/moine/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (248, 'Mont cendré', 'mont-cendre', NULL, NULL, '/lore/mont-cendre/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (249, 'Monts Couloirs', 'monts-couloirs', NULL, NULL, '/lore/monts-couloirs/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (250, 'Mora', 'mora', NULL, 'magie:vide', '/lore/mora/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (251, 'Mordhau', 'mordhau', 'Avec certaines armes de corps à corps (notamment les épées), prendre l''arme par la lame et frapper avec le manche. Elle peut ainsi faire des dégâts de frappe alors qu''elle en est incapable, mais a 30 % de chance de perdre un cran de solidité (exemple : plus de 70 au jet d''attaque).', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (252, 'Morfot', 'morfot', NULL, 'magie:potentiel-illimite', '/lore/morfot/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (253, 'Mort-vivant', 'mort-vivant', NULL, 'race:pure', '/races/mort-vivant/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (254, 'Mrode', 'mrode', NULL, NULL, '/lore/mrode/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (255, 'Nain', 'nain', NULL, 'race:pure', '/races/nain/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (256, 'Namazu', 'namazu-race', NULL, 'race:hybride', '/races/namazu/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (257, 'Namazu', 'namazu-classe', NULL, 'classe:raciales', '/classes/namazu/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (258, 'Naturel', 'naturel', 'Les points de compétence que l’on répartit soi-même, à la création (100 points, 20 au plus dans une compétence) puis à chaque niveau.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (259, 'Négatif maximal', 'negatif-maximal', 'L’opposé de la santé maximum (−30 pour 30 de santé). Un personnage dans le coma qui y descend n’a droit qu’à un seul jet de survie, et à deux fois ce négatif, il meurt sur le coup.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (260, 'Niveau de classe', 'niveau-de-classe', 'Le niveau propre à chaque classe, qui suit le niveau global. La classe donne ses dons à ses niveaux 1, 5, 10, 15 et 20, et sa spécialité à son niveau 10.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (261, 'Niveau de maîtrise', 'niveau-de-maitrise', 'Niveau de maîtrise d''un sort de 0 à 3, permettant d''en lancer un version améliorée. L''amélioration dépends du sort.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (262, 'Niveau de puissance magique', 'niveau-de-puissance-magique', 'Le niveau d’un sort, de 1 à 5. Un sort n’est accessible que si la puissance magique du personnage atteint son NPM.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (263, 'Niveau global', 'niveau-global', 'Le niveau du personnage, de 1 à 20, que fixe son total d’expérience. Il règle le niveau de ses classes et sa puissance magique.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (264, 'Notix', 'notix', NULL, 'magie:espace-temps', '/lore/notix/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (265, 'Océane', 'oceane', NULL, 'magie:eau', '/lore/oceane/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (266, 'Ocultomancien', 'ocultomancien', NULL, 'classe:magiques', '/classes/ocultomancien/', 1, NULL, NULL);
