INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (268, 'Olwman', 'olwman-classe', NULL, 'classe:raciales', '/classes/olwman/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (269, 'One shot', 'one-shot', 'Une histoire jouée en une seule séance, avec une fin fermée, qui ne laisse pas de suite. Voir aussi {{campagne|Campagne}}.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (270, 'Onir', 'onir', NULL, 'magie:ombre', '/lore/onir/', 1, NULL, NULL);
