INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (272, 'Ordre de la Glace Rouge', 'ordre-de-la-glace-rouge', NULL, NULL, '/lore/ordre-de-la-glace-rouge/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (273, 'Ordre de la mort', 'ordre-de-la-mort', NULL, NULL, '/lore/ordre-de-la-mort/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (274, 'Ordre des Abeilles', 'ordre-des-abeilles', NULL, NULL, '/lore/ordre-des-abeilles/', 1, NULL, NULL);
