INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (277, 'Origine du monde', 'origine-du-monde', NULL, NULL, '/lore/origine-du-monde/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (278, 'Orios', 'orios-race', NULL, 'race:hybride', '/races/orios/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (279, 'Orios', 'orios-classe', NULL, 'classe:raciales', '/classes/orios/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (280, 'Parade', 'parade', 'Bloquer un coup avec son arme ou son bouclier, avec la compétence Parade (Force). Voir aussi {{esquive|Esquive}} et {{defense-partielle|Défense partielle}}.', 'caracteristique:force', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (281, 'Parleur', 'parleur', NULL, 'classe:speciales', '/classes/parleur/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (282, 'Personnage joueur', 'personnage-joueur', 'Un personnage joueur, celui qu’incarne un joueur ; un personnage non joueur, que joue le MJ, comme tous ceux que croisent les personnages.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (283, 'Personnage non joueur', 'personnage-non-joueur', 'Voir {{personnage-joueur|Personnage joueur}}.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (284, 'Pièce élémentaire', 'piece-elementaire', 'Une pièce qui, posée sur une arme, une armure ou un vêtement, le transforme pour toujours en un équipement chargé de sa magie ; les bonus d’origine sont perdus.', NULL, '/ressources/armes/#pieces-elementaires', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (285, 'Plaine brillante', 'plaine-brillante', NULL, NULL, '/lore/plaine-brillante/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (286, 'Plaines sèches', 'plaines-seches', NULL, NULL, '/lore/plaines-seches/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (287, 'Plateau Tonnerre', 'plateau-tonnerre', NULL, NULL, '/lore/plateau-tonnerre/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (288, 'Points d’expérience', 'points-dexperience', 'Les points d’expérience. Leur total fixe le niveau global.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (289, 'Portée', 'portee', 'La distance qu’un sort ou une action peut atteindre. Celle d’une arme est le nombre de cases que parcourt son projectile, 1 pour une arme qui n’en écrit pas ; chaque diagonale y compte pour 2 cases.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (290, 'Posture', 'posture', 'L’attitude de combat que l’on prend ou change au début de son tour : on garde sa posture tant qu’on n’en change pas. Il en existe six : Offensif, Défensif, Neutre, Focus, Vigilance et Symbiose.', NULL, '/regles/les-postures/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (291, 'Potentiel illimité', 'potentiel-illimite', 'Magie unique donnant accès aux sort de toutes les magies au prix d''un épuisement physique constant.', 'magie:potentiel-illimite', '/magies/potentiel-illimite/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (292, 'Pierre précieuse', 'pierre-precieuse', 'Monnaies : le Ricken de fer (RF), le Ricken d’or (RO) et la Pierre précieuse (PP). 1 PP = 1 000 RO.', NULL, NULL, 1, 'pp', 'monnaie:pp');
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (293, 'Préparation (Mage Rouge)', 'preparation-mage-rouge', NULL, NULL, '/capacites/mage-rouge-preparation/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (294, 'Prétiré', 'pretire', 'Une fiche de personnage créée sur le site, visible de tous ; la liste des personnages les réunit.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (295, 'Prise en tenaille', 'prise-en-tenaille', 'Voir {{tenaille|Tenaille}}.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (296, 'Pugiliste', 'pugiliste', NULL, 'classe:melee', '/classes/pugiliste/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (297, 'Puissance magique', 'puissance-magique', 'Le niveau de magie du personnage, de 1 à 5, qui augmente avec son niveau global. Elle dit jusqu’à quel NPM il peut lancer des sorts, et multiplie ses emplacements de sorts.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (298, 'Race', 'race', 'Ensemble d''individus issus d''une même lignée commune.', NULL, '/races/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (299, 'Race pure', 'race-pure', 'En opposition aux races dites {{hybride-animal|hybride animal}}', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (300, 'Rater ses sortilèges', 'rater-ses-sortileges', NULL, NULL, '/regles/rater-ses-sortileges/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (301, 'Recharge longue', 'recharge-longue', 'Doit utiliser son action ou son mouvement pour recharger. Une propriété de certaines armes.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (302, 'Recharge très longue', 'recharge-tres-longue', 'Doit utiliser son action ET son mouvement pour recharger. Une propriété de certaines armes.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (303, 'Règles des métiers', 'regles-des-metiers', NULL, NULL, '/metiers/regles-des-metiers/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (304, 'Relations entre les races', 'relations-entre-les-races', NULL, NULL, '/lore/relations-entre-les-races/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (305, 'Remède', 'remede', 'Une potion contre une altération d’état. Le mineur la réduit d’un cran, le majeur de deux, le parfait la soigne entièrement.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (306, 'République Forestier', 'republique-forestier', NULL, NULL, '/lore/republique-forestier/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (307, 'République Noire', 'republique-noire', NULL, NULL, '/lore/republique-noire/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (308, 'Résistance', 'resistance', 'Résistance, faiblesse (ou vulnérabilité) : ce qui fait prendre deux fois moins de dégâts d’une magie, ou deux fois plus. Elles se comptent en crans qui s’additionnent : deux résistances à la même magie font une grande résistance, deux faiblesses une grande vulnérabilité, une résistance et une faiblesse s’annulent. L’armure, elle, résiste ou est faible à des types de coups physiques.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (309, 'Résistances et faiblesses', 'resistances-et-faiblesses', NULL, NULL, '/regles/resistances-et-faiblesses/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (310, 'Réussir une action', 'reussir-une-action', NULL, NULL, '/regles/reussir-une-action/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (311, 'Réussite critique', 'reussite-critique', 'Un résultat de 1 à 5 au D100, que des bonus élargissent (posture, score au-delà de 95 %, dons, sorts…), jamais au-delà de 1 à 15. L’action réussit de façon exceptionnelle : en attaque, les dégâts, bonus fixes compris, sont doublés.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (312, 'Ricken de fer', 'ricken-de-fer', 'Monnaies : le Ricken de fer (RF), le Ricken d’or (RO) et la Pierre précieuse (PP). 1 RO = 100 RF.', NULL, NULL, 1, 'rf', 'monnaie:rf');
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (313, 'Ricken d’or', 'ricken-dor', 'Monnaies : le Ricken de fer (RF), le Ricken d’or (RO) et la Pierre précieuse (PP). 1 RO = 100 RF, et 1 PP = 1 000 RO.', NULL, NULL, 1, 'ro', 'monnaie:ro');
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (314, 'Rokh', 'rokh-race', NULL, 'race:hybride', '/races/rokh/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (315, 'Rokh', 'rokh-classe', NULL, 'classe:raciales', '/classes/rokh/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (316, 'Ruines Rouges', 'ruines-rouges', NULL, NULL, '/lore/ruines-rouges/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (317, 'Sang', 'sang', '{{cout-secondaire|Ressource secondaire}} de la {{magie-du-sang|magie du Sang}}. C’est une réserve de 10 unités par défaut. Elle est utilisé pour la plupart des sorts en plus du {{chakra|chakra}}. La réserve de sang se recharge de 1 par tour en combat.', 'magie:sang', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (318, 'Santé', 'sante', 'Les points de vie du personnage. À 0 ou moins, il tombe dans le coma.', 'attribut:sante', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (319, 'Satyre', 'satyre-race', NULL, 'race:hybride', '/races/satyre/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (320, 'Satyre', 'satyre-classe', NULL, 'classe:raciales', '/classes/satyre/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (321, 'Saugnane', 'saugnane', NULL, NULL, '/lore/saugnane/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (322, 'Scénario one shot', 'scenario-one-shot', 'Voir {{one-shot|One shot}}.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (323, 'Score', 'score', 'Le pourcentage de réussite d’une compétence, qui vaut 10 × la caractéristique + les points naturels + les points acquis. Il faut faire son score ou moins au D100 pour réussir.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (324, 'Selcalibur', 'selcalibur', NULL, NULL, '/lore/selcalibur/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (325, 'S’entraîner', 'sentrainer', NULL, NULL, '/regles/s-entrainer-et-exercer-un-metier/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (326, 'Séraphe', 'seraphe', NULL, 'magie:sang', '/lore/seraphe/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (327, 'Séraphin', 'seraphin', NULL, 'magie:feu', '/lore/seraphin/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (328, 'Signe des pirates', 'signe-des-pirates', NULL, NULL, '/lore/signe-des-pirates/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (329, 'Situation actuelle', 'situation-actuelle', NULL, NULL, '/lore/situation-actuelle/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (330, 'Soir-matin', 'soir-matin', NULL, NULL, '/lore/soir-matin/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (331, 'Solidité', 'solidite', 'État de l''équipement. Une Solidité à 0 rend l''objet inutilisable et exige une réparation à l''aide d''un kit de réparation, ou d''une compétence d''artisanat adaptée ainsi que du même matériau que l''objet. La solidité compte les mauvais coups (un coup critique, le coup d’un adversaire très fort…) qu’un équipement peut encaisser. Une armure en a une par partie (le casque, le torse, chaque bras, chaque jambe), sauf une armure à cran de solidité uni, qui n’en a qu’une.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (332, 'Sort fer', 'sort-fer', 'Type de sort d''amélioration qui s''applique sur une arme. Faisant qu''elle inflige désormais des dégâts magiques.', NULL, NULL, 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (333, 'Sort grenade', 'sort-grenade', 'Type particulier de sort provoquant une explosion localisée.', NULL, NULL, 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (334, 'spéciale', 'speciale', NULL, NULL, NULL, 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (335, 'Spécialité', 'specialite', 'L’embranchement d’une classe, qui se choisit quand elle atteint le niveau 10 ; la page de la classe en donne les dons.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (336, 'Sprint', 'sprint', 'Doubler la distance parcourue pendant son tour. C’est l’action du tour : impossible d’attaquer après un sprint.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (337, 'Super Gemme', 'super-gemme', NULL, NULL, '/lore/super-gemme/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (338, 'Temple de la Foudre', 'temple-de-la-foudre', NULL, 'magie:foudre', '/lore/temple-de-la-foudre/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (339, 'Temple de la Glace', 'temple-de-la-glace', NULL, 'magie:glace', '/lore/temple-de-la-glace/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (340, 'Temple de la Lumière', 'temple-de-la-lumiere', NULL, 'magie:lumiere', '/lore/temple-de-la-lumiere/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (341, 'Temple de la Terre', 'temple-de-la-terre', NULL, 'magie:terre', '/lore/temple-de-la-terre/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (342, 'Temple de l’Eau', 'temple-de-leau', NULL, 'magie:eau', '/lore/temple-de-leau/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (343, 'Temple de l’Espace/Temps', 'temple-de-lespace-temps', NULL, 'magie:espace-temps', '/lore/temple-de-lespace-temps/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (344, 'Temple de l’Ombre', 'temple-de-lombre', NULL, 'magie:ombre', '/lore/temple-de-lombre/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (345, 'Temple de Vent', 'temple-de-vent', NULL, 'magie:vent', '/lore/temple-de-vent/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (346, 'Temple du Feu', 'temple-du-feu', NULL, 'magie:feu', '/lore/temple-du-feu/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (347, 'Temple du Savoir', 'temple-du-savoir', NULL, 'magie:vide', '/lore/temple-du-savoir/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (348, 'Temple noir', 'temple-noir', NULL, 'magie:corruption', '/lore/temple-noir/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (349, 'Temples/Cultes/Guildes', 'temples-cultes-guildes', NULL, NULL, '/lore/temples-cultes-guildes/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (350, 'Tenaille', 'tenaille', 'Un ennemi encerclé au corps à corps par des alliés placés sur des cases opposées ; chaque allié de plus donne un avantage, jusqu’à quatre.', NULL, '/regles/prise-en-tenaille-et-zone-d-influence/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (351, 'Terre grise', 'terre-grise', NULL, NULL, '/lore/terre-grise/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (352, 'Tisseurs de soi', 'tisseurs-de-soi', NULL, NULL, '/lore/tisseurs-de-soi/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (353, 'Tofrom', 'tofrom', NULL, 'magie:potentiel-illimite', '/lore/tofrom/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (354, 'Tounne', 'tounne', NULL, NULL, '/lore/tounne/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (355, 'Tour', 'tour', 'En combat, le temps se découpe en tours ; chacun agit à son tour, dans l’ordre de l’initiative, puis un nouveau tour commence.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (356, 'Tour de charge', 'tour-de-charge', 'Un sort qui requiert un tour de charge doit prendre un tour complet sans interruption avant d''être lancé. Annulé par la posture focus', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (357, 'Tueur', 'tueur', NULL, 'classe:melee', '/classes/tueur/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (358, 'Umbro', 'umbro', NULL, 'magie:ombre', '/lore/umbro/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (359, 'Un maître du Jeu', 'un-maitre-du-jeu', NULL, NULL, '/mj/un-maitre-du-jeu/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (360, 'Vampires primordiaux', 'vampires-primordiaux', NULL, NULL, '/lore/vampires-primordiaux/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (361, 'Ville-Oeil', 'ville-oeil', NULL, NULL, '/lore/ville-oeil/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (362, 'Vitesse', 'vitesse', 'Le nombre de cases que le personnage parcourt en un tour. Il en a deux, sur terre et à la nage : celles de sa race, que l’équipement, les accessoires et les sorts peuvent changer.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (363, 'Voleur', 'voleur', NULL, 'classe:melee', '/classes/voleur/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (364, 'Volt', 'volt', NULL, 'magie:foudre', '/lore/volt/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (365, 'Vulnérabilité', 'vulnerabilite', 'Voir {{resistance|Résistance}}.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (366, 'Xendown', 'xendown', NULL, NULL, '/lore/xendown/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (367, 'Zone d’influence', 'zone-dinfluence', 'Les cases devant un adversaire, derrière lui, à sa gauche et à sa droite. Y entrer puis la traverser, ou la quitter, lui permet une {{attaque-dopportunite|attaque d’opportunité}}, avec ses limites.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (368, 'Agilité', 'agilite', '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{arme-legere|Arme Légère}}, {{equilibre|Équilibre}}, {{esquive|Esquive}}, {{reflexe|Réflexe}} et {{ruse|Ruse}}. Renforée par les magies {{magie-innee|innées}} du {{magie-du-vent|Vent}} ou de la {{magie-de-la-foudre|Foudre}}', 'caracteristique:agilite', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (369, 'Ambidextrie', 'ambidextrie', 'Une arme de mêlée dans chaque main : −20 % à l’attaque de la main directrice, −40 % à celle de la main secondaire ; le malus est divisé par deux pour la main qui tient une dague et par deux pour la classe Bimane, les deux se cumulant.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (370, 'Arbalète', 'arbalete', 'Une compétence liée aux armes qui tirent des carreaux. Caractéristique : {{perception|Perception}}.', 'caracteristique:perception', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (371, 'Arc', 'arc', 'Une compétence liée aux armes qui tirent des flèches. Caractéristique : {{force|Force}}.', 'caracteristique:force', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (372, 'Arme Légère', 'arme-legere', 'Une compétence liée à l’utilisation d’arme de catégorie légère. Caractéristique : {{agilite|Agilité}}.', 'caracteristique:agilite', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (373, 'Arme Lourde', 'arme-lourde', 'Une compétence liée à l’utilisation d’arme de catégorie lourde. Caractéristique : {{force|Force}}.', 'caracteristique:force', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (374, 'Athlétisme', 'athletisme', 'Utilisée lors de tests où la force pure est mise à l''épreuve. (équivalent d’équilibre pour l’agilité) Caractéristique : {{force|Force}}.', 'caracteristique:force', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (375, 'Calme', 'calme', 'Faire preuve de sang-froid dans les situations dangereuses. Caractéristique : {{volonte|Volonté}}.', 'caracteristique:volonte', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (376, 'Concentration', 'concentration', 'Permet de rester concentré sur son sort (utilisé par les mages rouge, bleu et vert pour lancer leurs sorts). Caractéristique : {{volonte|Volonté}}.', 'caracteristique:volonte', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (377, 'Connaissance', 'connaissance', 'Une grande connaissance sur de vastes sujets. Caractéristique : {{intelligence|Intelligence}}.', 'caracteristique:intelligence', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (378, 'Diplomatie', 'diplomatie', 'Persuader sans violence, ni contrainte. Caractéristique : {{social|Social}}.', 'caracteristique:social', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (379, 'Distinction', 'distinction', 'L''art de voir les choses en profondeur, de sentir, d''écouter, de ressentir. Caractéristique : {{perception|Perception}}.', 'caracteristique:perception', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (380, 'Dressage', 'dressage', 'Liée au dressage d''animaux ou monstres destinés à être des familiers. Caractéristique : {{social|Social}}.', 'caracteristique:social', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (381, 'Équilibre', 'equilibre', 'L''art de garder l’équilibre dans différentes situations. (équivalent d’athlétisme pour la force) Caractéristique : {{agilite|Agilité}}.', 'caracteristique:agilite', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (382, 'Fermeté', 'fermete', 'Mieux résister aux attaques mentales, aux attaques sur le psychique. Caractéristique : {{volonte|Volonté}}.', 'caracteristique:volonte', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (383, 'Force', 'force', '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{arc|Arc}}, {{arme-lourde|Arme Lourde}}, {{athletisme|Athlétisme}}, {{parade|Parade}} et {{stabilite|Stabilité}}. Renforée par les magies {{magie-innee|innées}} du {{magie-du-sang|Sang}} ou de la {{magie-de-la-terre|Terre}}', 'caracteristique:force', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (384, 'Intelligence', 'intelligence', '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{connaissance|Connaissance}}, {{magie|Magie}}, {{medecine|Médecine}}, {{psychologie|Psychologie}} et {{vie-en-nature|Vie en nature}}}. Renforcée par les magies {{magie-innee|innées}} de l''{{magie-de-larcane|Arcane}}, de la {{magie-de-la-corruption|Corruption}}, de l''{{magie-de-lespace-temps|Espace/Temps}} ou de la{{magie-de-la-glace|Glace}}', 'caracteristique:intelligence', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (385, 'Intimidation', 'intimidation', 'Persuader avec violence, sous la contrainte. Caractéristique : {{social|Social}}.', 'caracteristique:social', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (386, 'Jet d’attaque', 'jet-dattaque', 'Le D100 de l’attaquant : il doit faire son {{score|score}} ou moins dans la compétence qui sert à l’attaque (celle de l’arme, ou Magie, ou Concentration pour un sort).', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (387, 'Jet de défense', 'jet-de-defense', 'Le D100 de la cible qui pare ou esquive. Pour bloquer entièrement le coup, il doit réussir et donner un résultat égal ou inférieur à celui de l’attaquant ; contre une réussite critique, seule une réussite critique compte.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (388, 'Localisation des dégâts', 'localisation-des-degats', 'Viser la tête, un bras ou une jambe plutôt que le corps : chaque zone a son malus pour toucher et son effet en plus ; le corps n’a ni malus ni effet.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (389, 'Magie', 'magie', 'La compétence liée aux sortilèges et la capacité à les lancer correctement. Caractéristique : {{intelligence|Intelligence}}.', 'caracteristique:intelligence', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (390, 'Manipulation', 'manipulation', 'L''art du mensonge, du sophisme, du détournement de regard et du déplacement de but. Caractéristique : {{social|Social}}.', 'caracteristique:social', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (391, 'Médecine', 'medecine', 'Liée à tous les soins physiques que la magie ne peut soigner. Caractéristique : {{intelligence|Intelligence}}.', 'caracteristique:intelligence', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (393, 'Négociation', 'negociation', 'Liée à l''art de négocier quelque chose. Caractéristique : {{social|Social}}.', 'caracteristique:social', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (394, 'Observation', 'observation', 'Utiliser sa vue pour bien connaître son environnement en général. Caractéristique : {{perception|Perception}}.', 'caracteristique:perception', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (395, 'Orientation', 'orientation', 'Pour bien lire une carte et ne pas se perdre. Caractéristique : {{perception|Perception}}.', 'caracteristique:perception', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (396, 'Perception', 'perception', '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{arbalete|Arbalète}}, {{distinction|Distinction}}, {{observation|Observation}}, {{orientation|Orientation}} et {{sabotage|Sabotage}}. Renforcée par les magies {{magie-innee|innées}} de la {{magie-de-la-lumiere|Lumière}} ou de l''{{magie-de-lombre|Ombre}}', 'caracteristique:perception', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (397, 'Psychologie', 'psychologie', 'Permet de comprendre la psychologie de sa cible, déceler le mensonge dans le comportement et les paroles. Caractéristique : {{intelligence|Intelligence}}.', 'caracteristique:intelligence', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (398, 'Réflexe', 'reflexe', 'Laisser son corps agir de lui-même. (équivalent de stabilité pour la force) Caractéristique : {{agilite|Agilité}}.', 'caracteristique:agilite', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (399, 'Réussites / échecs / critiques', 'reussites-echecs-critiques', NULL, NULL, '/regles/reussites-echecs-et-critiques/', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (400, 'Ruse', 'ruse', '"Parfois, ne pas se battre est la meilleure des victoires" Il est nécessaire de réussir un jet de ruse pour une {{attaque-discrete|attaque discrète}}. Caractéristique : {{agilite|Agilité}}.', 'caracteristique:agilite', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (401, 'Sabotage', 'sabotage', 'Créer des pièges, les désarmer ou même les retourner contre les ennemis. Caractéristique : {{perception|Perception}}.', 'caracteristique:perception', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (402, 'Social', 'social', '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{diplomatie|Diplomatie}}, {{dressage|Dressage}}, {{intimidation|Intimidation}}, {{manipulation|Manipulation}} et {{negociation|Négociation}}. Renforcée par les magies {{magie-innee|innées}} du {{magie-du-feu|Feu}} ou de l''{{magie-de-leau|Eau}}.', 'caracteristique:social', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (403, 'Stabilité', 'stabilite', 'Être capable de tenir sa position quand le sol tremble, porter une charge longtemps, etc. (équivalent de réflexe pour l’agilité) Caractéristique : {{force|Force}}.', 'caracteristique:force', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (404, 'Survie', 'survie', '"Le corps s’accroche à la vie, telle une sangsue sur une veine" cette compétence est utilisée dans le cas d''un coma. Caractéristique : {{volonte|Volonté}}.', 'caracteristique:volonte', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (405, 'Vie en nature', 'vie-en-nature', 'Comprendre la nature, ses bienfaits. Caractéristique : {{intelligence|Intelligence}}.', 'caracteristique:intelligence', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (406, 'Vigueur', 'vigueur', 'Mieux résister aux {{alteration-detat|altérations d''états}} physiques comme le poison, les maladies ou les brûlures. Caractéristique : {{volonte|Volonté}}.', 'caracteristique:volonte', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (407, 'Volonté', 'volonte', '{{caracteristique|Caractéristique}} regroupant les {{competence|compétences}} : {{calme|Calme}}, {{concentration|Concentration}}, {{fermete|Fermeté}}, {{survie|Survie}} et {{vigueur|Vigueur}}. Renforcée par les magies {{magie-innee|innées}} du {{magie-du-vide|Vide}} ou de la {{magie-de-la-necromancie|Nécromancie}}.', 'caracteristique:volonte', NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (408, 'Fongoïde', 'fongoide', NULL, 'race:pure', '/races/fongoide/', 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (409, 'Gémidien', 'gemidien', NULL, 'race:pure', '/races/gemidien/', 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (410, 'Non-mort', 'non-mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (411, 'Bête', 'bete', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (412, 'Mécanique', 'mecanique', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (413, 'Démon', 'demon', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (414, 'Immatériel', 'immateriel', 'Cette créature est naturellement immunisée aux dégâts physiques (armes), seules la magie, une arme spectrale ou une arme sous l’effet d’un {{sort-fer|sort “fer”}} peuvent la toucher.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (415, 'Désarmement', 'desarmement', 'Tout sort, don ou capacité qui fait perdre son arme au porteur.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (416, 'Avantage', 'avantage', 'On lance deux fois le même jet et on ignore le jet le plus défavorable au lanceur.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (417, 'Super Magie', 'super-magie', 'Réservé aux État de connexion profonde avec sa magie innée, donnant accès à plus de sorts.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (418, 'Mono-magie', 'mono-magie', 'Personnage ne disposant que de sa magie innée.', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (419, 'Bi-magie', 'bi-magie', 'Personnage disposant à la fois de sa {{magie-innee|Magie innée}} et d''une {{magie-acquise|Magie acquise}}', NULL, NULL, 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (420, 'Mode Hyper 100%', 'mode-hyper-100', 'État amplifié du {{mode-hyper|Mode Hyper}}', NULL, '/regles/le-mode-hyper/', 0, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (421, 'Loyal Bon', 'loyal-bon', 'Le Loyal Bon cherche à faire le bien tout en accordant une grande importance à l’ordre, au devoir et au collectif.', 'alignement:loyal-bon', '/regles/alignement/#loyal-bon', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (422, 'Loyal Neutre', 'loyal-neutre', 'Le Loyal Neutre accorde la priorité à l’ordre, au devoir et au fonctionnement du collectif, sans que le Bien ou le Mal ne constitue nécessairement sa principale préoccupation.', 'alignement:loyal-neutre', '/regles/alignement/#loyal-neutre', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (423, 'Loyal Mauvais', 'loyal-mauvais', 'Le Loyal Mauvais cherche à satisfaire ses propres intérêts tout en s’appuyant sur l’ordre, la hiérarchie et les règles.', 'alignement:loyal-mauvais', '/regles/alignement/#loyal-mauvais', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (424, 'Neutre Bon', 'neutre-bon', 'Le Neutre Bon cherche avant tout à faire le bien et à protéger les autres, sans accorder une importance particulière à l’ordre ou à la liberté.', 'alignement:neutre-bon', '/regles/alignement/#neutre-bon', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (425, 'Neutre', 'neutre', 'Le Neutre ne place aucune des quatre tendances au-dessus des autres.', 'alignement:neutre', '/regles/alignement/#neutre', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (426, 'Neutre Mauvais', 'neutre-mauvais', 'Le Neutre Mauvais place ses propres intérêts au-dessus de ceux des autres, sans attachement particulier à l’ordre ou au chaos.', 'alignement:neutre-mauvais', '/regles/alignement/#neutre-mauvais', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (427, 'Chaotique Bon', 'chaotique-bon', 'Le Chaotique Bon cherche à faire le bien tout en accordant une grande importance à la liberté et au libre arbitre.', 'alignement:chaotique-bon', '/regles/alignement/#chaotique-bon', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (428, 'Chaotique Neutre', 'chaotique-neutre', 'Le Chaotique Neutre place la liberté individuelle au-dessus de l’ordre et des contraintes imposées par le collectif.', 'alignement:chaotique-neutre', '/regles/alignement/#chaotique-neutre', 1, NULL, NULL);
INSERT INTO mot_cle (id, libelle, cle, description, couleur, url, verrou, monnaie_id, icone) VALUES (429, 'Chaotique Mauvais', 'chaotique-mauvais', 'Le Chaotique Mauvais place sa liberté et ses propres désirs au-dessus de toute considération pour les autres.', 'alignement:chaotique-mauvais', '/regles/alignement/#chaotique-mauvais', 1, NULL, NULL);
